-- Clear diagnostic questions with registry-backed public table stimuli.
-- Never change the question set underneath an active assessment session.
SET LOCAL lock_timeout = '5s';
LOCK TABLE public.assessment_sessions IN SHARE ROW EXCLUSIVE MODE;
DO $$
BEGIN
 IF EXISTS (SELECT 1 FROM public.assessment_sessions s JOIN public.assessments a ON a.id=s.assessment_id
  WHERE a.slug='pre-test-basis-data' AND s.status='IN_PROGRESS') THEN
  RAISE EXCEPTION 'Finish active pre-tests before revising diagnostic questions';
 END IF;
 IF (SELECT count(*) FROM public.assessment_items i JOIN public.assessments a ON a.id=i.assessment_id WHERE a.slug='pre-test-basis-data') <> 10 THEN
  RAISE EXCEPTION 'Expected ten diagnostic items';
 END IF;
END $$;
WITH revisions AS (SELECT * FROM jsonb_to_recordset($questions$[{"slug":"pre-test-basis-data","position":1,"title":"Mengenali kolom","prompt":"Perhatikan tabel `books` di bawah. Petugas ingin mengambil **judul buku**, bukan nomor buku atau jumlah stok.\n\n**Kolom mana yang menyimpan judul buku?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"title"},{"id":"b","text":"book_id"},{"id":"c","text":"stock"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":2,"title":"Memilih identitas record","prompt":"Tabel `students` menyimpan data mahasiswa. Nama dan angkatan boleh sama untuk beberapa mahasiswa. Nomor `student_id` diberikan kepada satu mahasiswa dan tidak boleh kosong.\n\nPetugas perlu memilih satu mahasiswa secara tepat tanpa tertukar. **Kolom mana yang paling sesuai dijadikan primary key atau identitas unik setiap mahasiswa?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"name"},{"id":"b","text":"student_id"},{"id":"c","text":"cohort"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"campus","tables":["students"],"relations":false}}},{"slug":"pre-test-basis-data","position":3,"title":"Memahami hubungan antartabel","prompt":"Perpustakaan menyimpan data buku dalam `books` dan data penulis dalam `authors`.\n\nBuku **Algoritma Ringkas** memiliki `author_id = 2`. Pada tabel `authors`, nomor tersebut dimiliki oleh **Budi**.\n\n**Mengapa tabel buku menyimpan `author_id`?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"Untuk menentukan urutan buku berdasarkan judul."},{"id":"b","text":"Untuk menyimpan jumlah stok buku."},{"id":"c","text":"Untuk menghubungkan setiap buku dengan data penulisnya."},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["authors","books"],"relations":false}}},{"slug":"pre-test-basis-data","position":4,"title":"Menampilkan satu kolom","prompt":"Petugas ingin menampilkan **judul seluruh buku** dari tabel `books`. Hasilnya harus memiliki satu kolom saja, yaitu `title`.\n\n**Query mana yang memenuhi kebutuhan tersebut?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"SELECT title FROM books;"},{"id":"b","text":"SELECT title, stock FROM books;"},{"id":"c","text":"SELECT * FROM books;"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":5,"title":"Menentukan hasil filter","prompt":"Perpustakaan hanya akan meminjamkan buku untuk kegiatan kelompok jika stoknya **lebih dari 2**.\n\nPetugas menjalankan query:\n\n```sql\nSELECT title\nFROM books\nWHERE stock > 2;\n```\n\n**Judul buku mana saja yang masuk dalam hasil query? Abaikan urutan hasilnya.**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"Dasar Basis Data dan Pengantar SQL."},{"id":"b","text":"Dasar Basis Data dan Algoritma Ringkas."},{"id":"c","text":"Algoritma Ringkas dan Pengantar SQL."},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":6,"title":"Menggabungkan data buku dan penulis","prompt":"Petugas ingin membuat laporan yang menampilkan **judul buku beserta nama penulisnya**.\n\nJudul tersedia di tabel `books`, sedangkan nama penulis tersedia di tabel `authors`.\n\n**Kondisi JOIN mana yang memasangkan buku dengan penulis yang benar?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"books.title = authors.name"},{"id":"b","text":"books.book_id = authors.author_id"},{"id":"c","text":"books.author_id = authors.author_id"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["authors","books"],"relations":false}}},{"slug":"pre-test-basis-data","position":7,"title":"Menghitung record","prompt":"Setiap baris pada tabel `books` mewakili **satu judul buku**. Kolom `stock` menunjukkan jumlah eksemplar yang tersedia.\n\nPetugas menjalankan:\n\n```sql\nSELECT COUNT(*)\nFROM books;\n```\n\n**Angka berapa yang dihasilkan query tersebut?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"4"},{"id":"b","text":"10"},{"id":"c","text":"3"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":8,"title":"Menambahkan record baru","prompt":"Perpustakaan menerima judul baru bernama **Belajar SQL** yang belum ada dalam tabel `books`.\n\nPetugas ingin **menambahkan satu baris baru**, tanpa mengubah atau menghapus buku yang sudah tercatat.\n\n**Perintah SQL mana yang digunakan?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"UPDATE"},{"id":"b","text":"INSERT INTO"},{"id":"c","text":"SELECT"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":9,"title":"Mengubah satu record","prompt":"Stok **Algoritma Ringkas**, dengan `book_id = 30`, bertambah dari **3 menjadi 4**.\n\nPetugas harus memperbarui stok buku tersebut. Stok semua buku lainnya harus tetap sama.\n\n**Query mana yang tepat?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"UPDATE books SET stock = 4;"},{"id":"b","text":"UPDATE books SET stock = 4 WHERE author_id = 1;"},{"id":"c","text":"UPDATE books SET stock = 4 WHERE book_id = 30;"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":10,"title":"Memeriksa target sebelum menghapus","prompt":"Perpustakaan akan menghapus **Logika Data**, dengan `book_id = 20`, dari katalog.\n\nSebelum menjalankan DELETE, petugas ingin memastikan bahwa kondisi penghapusan memilih **buku itu saja**, tanpa memilih buku lain.\n\n**Query SELECT mana yang sebaiknya digunakan untuk memeriksa target?**","publicConfig":{"mode":"choice","options":[{"id":"a","text":"SELECT * FROM books WHERE book_id = 20;"},{"id":"b","text":"SELECT * FROM books WHERE author_id = 1;"},{"id":"c","text":"SELECT * FROM books WHERE stock > 0;"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books","authors"],"relations":false}}}]$questions$::jsonb) AS r(slug text, position integer, title text, prompt text, "publicConfig" jsonb))
UPDATE public.assessment_items i SET title=r.title,prompt=r.prompt,public_config=r."publicConfig"
FROM revisions r, public.assessments a WHERE a.slug=r.slug AND i.assessment_id=a.id AND i.position=r.position;
-- No private answer or historical session/result data is changed.
